Index: PortableDVEImplementation.html
===================================================================
--- PortableDVEImplementation.html	
+++ PortableDVEImplementation.html	
@@ -1,1585 +1,1585 @@
 <!DOCTYPE html>
 <html lang="en">
 <head>
 <meta charset="UTF-8">
 <meta name="viewport" content="width=device-width, initial-scale=1.0">
 <title>Portable DVE — KNIRV Network Design Specification</title>
 <style>
 *,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
 :root{
   --bg0:#040810;--bg1:#080f1e;--bg2:#0d1628;--bg3:#121e35;--bg4:#18273f;
   --cyan:#00d4ff;--cyan2:#0099bb;--purple:#7c3aed;--green:#10b981;--amber:#f59e0b;--red:#ef4444;
   --t1:#eef2ff;--t2:#94a3b8;--t3:#475569;
   --border:rgba(0,212,255,0.12);--border2:rgba(0,212,255,0.28);
   --mono:'JetBrains Mono','Fira Code',monospace;
   --sans:'Inter',system-ui,sans-serif;
   --term-bg:#020810;--term-fg:#b8d4f0;
 }
 html{scroll-behavior:smooth}
 body{background:var(--bg0);color:var(--t1);font-family:var(--sans);font-size:15px;line-height:1.65}

 /* NAV */
 nav{position:sticky;top:0;z-index:200;display:flex;align-items:center;gap:1.5rem;padding:.65rem 2rem;
   background:rgba(4,8,16,.96);border-bottom:1px solid var(--border);backdrop-filter:blur(16px)}
 .logo{font-family:var(--mono);font-size:.8rem;font-weight:700;color:var(--cyan);letter-spacing:.12em;text-decoration:none}
 nav ul{display:flex;gap:1.25rem;list-style:none;margin-left:auto}
 nav a{color:var(--t2);text-decoration:none;font-size:.82rem;font-weight:500;transition:color .15s}
 nav a:hover{color:var(--cyan)}
 .nbadge{font-family:var(--mono);font-size:.68rem;padding:.18rem .55rem;background:rgba(0,212,255,.08);
   border:1px solid var(--border2);border-radius:999px;color:var(--cyan)}

 /* HERO */
 .hero{padding:5rem 2rem 4rem;text-align:center;position:relative;overflow:hidden}
 .hero::before{content:'';position:absolute;top:-30%;left:50%;transform:translateX(-50%);
   width:900px;height:700px;background:radial-gradient(ellipse,rgba(0,212,255,.07) 0%,transparent 65%);pointer-events:none}
 .hero::after{content:'';position:absolute;top:20%;left:30%;
   width:500px;height:500px;background:radial-gradient(ellipse,rgba(124,58,237,.05) 0%,transparent 65%);pointer-events:none}
 .htag{display:inline-block;font-family:var(--mono);font-size:.72rem;color:var(--cyan);
   border:1px solid var(--border2);padding:.25rem .75rem;border-radius:999px;margin-bottom:1.5rem;letter-spacing:.1em}
 h1{font-size:clamp(2.2rem,5vw,3.8rem);font-weight:800;letter-spacing:-.025em;line-height:1.08;
   background:linear-gradient(135deg,var(--t1) 0%,var(--cyan) 55%,var(--purple) 100%);
   -webkit-background-clip:text;-webkit-text-fill-color:transparent;margin-bottom:1.1rem}
 .hsub{font-size:1.1rem;color:var(--t2);max-width:620px;margin:0 auto 2.5rem}
 .hpills{display:flex;gap:.75rem;justify-content:center;flex-wrap:wrap;margin-bottom:3rem}
 .pill{font-family:var(--mono);font-size:.72rem;padding:.3rem .8rem;border-radius:999px;font-weight:500}
 .pill-cyan{background:rgba(0,212,255,.1);border:1px solid rgba(0,212,255,.3);color:var(--cyan)}
 .pill-purple{background:rgba(124,58,237,.1);border:1px solid rgba(124,58,237,.3);color:#a78bfa}
 .pill-green{background:rgba(16,185,129,.1);border:1px solid rgba(16,185,129,.3);color:#34d399}
 .pill-amber{background:rgba(245,158,11,.1);border:1px solid rgba(245,158,11,.3);color:#fbbf24}

 /* SECTION */
 section{padding:4rem 2rem;max-width:1200px;margin:0 auto}
 section+section{border-top:1px solid var(--border)}
 .sec-label{font-family:var(--mono);font-size:.72rem;color:var(--cyan);letter-spacing:.15em;margin-bottom:.75rem}
 h2{font-size:1.9rem;font-weight:700;margin-bottom:1rem}
 h3{font-size:1.15rem;font-weight:600;margin-bottom:.6rem;color:var(--t1)}
 p{color:var(--t2);margin-bottom:1rem}
 .lead{font-size:1.05rem;color:var(--t2);max-width:760px;margin-bottom:2rem}

 /* CARDS */
 .grid{display:grid;gap:1.25rem}
 .grid-2{grid-template-columns:repeat(auto-fit,minmax(340px,1fr))}
 .grid-3{grid-template-columns:repeat(auto-fit,minmax(280px,1fr))}
 .card{background:var(--bg2);border:1px solid var(--border);border-radius:12px;padding:1.5rem;
   transition:border-color .2s,transform .2s}
 .card:hover{border-color:var(--border2);transform:translateY(-2px)}
 .card-icon{font-size:1.5rem;margin-bottom:.75rem}
 .card h3{margin-bottom:.5rem}
 .card p{font-size:.88rem;margin:0}

 /* ARCH DIAGRAM */
 .arch-wrap{background:var(--bg1);border:1px solid var(--border);border-radius:16px;padding:2rem;margin:2rem 0;overflow-x:auto}
 .arch-wrap svg{width:100%;max-width:900px;display:block;margin:0 auto}

 /* CODE BLOCKS */
 .code-tabs{margin:1.5rem 0}
 .tab-bar{display:flex;gap:0;border-bottom:1px solid var(--border)}
 .tab-btn{font-family:var(--mono);font-size:.78rem;padding:.5rem 1.1rem;background:none;border:none;
   color:var(--t3);cursor:pointer;border-bottom:2px solid transparent;transition:all .15s;white-space:nowrap}
 .tab-btn.active{color:var(--cyan);border-bottom-color:var(--cyan)}
 .tab-btn:hover:not(.active){color:var(--t2)}
 .tab-pane{display:none}
 .tab-pane.active{display:block}
 pre{background:var(--bg1);border:1px solid var(--border);border-radius:10px;
   padding:1.25rem 1.5rem;overflow-x:auto;font-family:var(--mono);font-size:.8rem;line-height:1.7;margin:.75rem 0}
 code{font-family:var(--mono);font-size:.82em}
 .kw{color:#c792ea}.fn{color:#82aaff}.str{color:#c3e88d}.cm{color:#546e7a;font-style:italic}
 .ty{color:#ffcb6b}.num{color:#f78c6c}.op{color:#89ddff}.pk{color:#00d4ff}

 /* LAYERS */
 .layers{display:flex;flex-direction:column;gap:.75rem;margin:1.5rem 0}
 .layer{display:flex;align-items:center;gap:1rem;background:var(--bg2);border:1px solid var(--border);
   border-radius:10px;padding:1rem 1.25rem}
 .layer-num{font-family:var(--mono);font-size:.7rem;font-weight:700;padding:.2rem .5rem;
   border-radius:6px;min-width:2.2rem;text-align:center}
 .l0 .layer-num{background:rgba(0,212,255,.15);color:var(--cyan)}
 .l1 .layer-num{background:rgba(16,185,129,.15);color:var(--green)}
 .l2 .layer-num{background:rgba(245,158,11,.15);color:var(--amber)}
 .l3 .layer-num{background:rgba(124,58,237,.15);color:#a78bfa}
 .layer-info{flex:1}
 .layer-title{font-weight:600;font-size:.95rem;margin-bottom:.2rem}
 .layer-desc{font-size:.83rem;color:var(--t2)}
 .layer-badge{font-family:var(--mono);font-size:.68rem;padding:.15rem .5rem;border-radius:6px;white-space:nowrap}

 /* TERMINAL */
 .term-container{background:var(--term-bg);border:1px solid rgba(0,212,255,.2);border-radius:12px;
   overflow:hidden;margin:1.5rem 0;box-shadow:0 0 40px rgba(0,212,255,.08)}
 .term-bar{background:rgba(255,255,255,.04);border-bottom:1px solid rgba(255,255,255,.07);
   display:flex;align-items:center;gap:.75rem;padding:.55rem 1rem}
 .term-dots{display:flex;gap:.4rem}
 .term-dot{width:12px;height:12px;border-radius:50%}
 .td1{background:#ff5f56}.td2{background:#ffbd2e}.td3{background:#27c93f}
 .term-title{font-family:var(--mono);font-size:.72rem;color:var(--t3);margin:0 auto}
 #terminal{height:420px;overflow-y:auto;padding:1rem 1.25rem;font-family:var(--mono);
   font-size:.82rem;line-height:1.6;color:var(--term-fg);cursor:text}
 #terminal::-webkit-scrollbar{width:6px}
 #terminal::-webkit-scrollbar-thumb{background:rgba(0,212,255,.2);border-radius:3px}
 .term-input-row{display:flex;align-items:center;padding:.4rem 1.25rem .75rem;
   border-top:1px solid rgba(255,255,255,.05)}
 .term-prompt-str{font-family:var(--mono);font-size:.82rem;color:#00ff88;white-space:nowrap}
 #term-input{flex:1;background:none;border:none;outline:none;font-family:var(--mono);
   font-size:.82rem;color:var(--term-fg);caret-color:var(--cyan)}

 /* INTEGRATION TABLE */
 .itbl{width:100%;border-collapse:collapse;font-size:.85rem;margin:1rem 0}
 .itbl th{text-align:left;font-family:var(--mono);font-size:.72rem;color:var(--t3);
   padding:.5rem 1rem;border-bottom:1px solid var(--border);font-weight:500;letter-spacing:.08em}
 .itbl td{padding:.65rem 1rem;border-bottom:1px solid var(--border);vertical-align:top}
 .itbl td:first-child{font-family:var(--mono);font-size:.78rem;color:var(--cyan)}
 .itbl td:nth-child(2){color:var(--t2)}
 .itbl tr:last-child td{border-bottom:none}

 /* CALLOUT */
 .callout{background:rgba(0,212,255,.06);border:1px solid rgba(0,212,255,.2);border-left:3px solid var(--cyan);
   border-radius:8px;padding:1rem 1.25rem;margin:1rem 0}
 .callout p{margin:0;font-size:.9rem}
 .callout-warn{background:rgba(245,158,11,.06);border-color:rgba(245,158,11,.3);border-left-color:var(--amber)}
 .callout-warn p{color:#fbbf24}

 /* BUILD STEPS */
 .steps{counter-reset:step;display:flex;flex-direction:column;gap:1rem;margin:1.5rem 0}
 .step{display:flex;gap:1rem;align-items:flex-start}
 .step::before{counter-increment:step;content:counter(step);min-width:2rem;height:2rem;
   display:flex;align-items:center;justify-content:center;background:rgba(0,212,255,.1);
   border:1px solid var(--border2);border-radius:50%;font-family:var(--mono);font-size:.78rem;
   color:var(--cyan);font-weight:700;flex-shrink:0;margin-top:.1rem}
 .step-body{flex:1}
 .step-title{font-weight:600;margin-bottom:.3rem}
 .step-desc{font-size:.85rem;color:var(--t2)}

 /* FOOTER */
 footer{text-align:center;padding:2rem;color:var(--t3);font-size:.8rem;
   border-top:1px solid var(--border);font-family:var(--mono)}
 </style>
 </head>
 <body>

 <nav>
   <a class="logo" href="#">KNIRV // PORTABLE DVE</a>
   <ul>
     <li><a href="#approach">Approach</a></li>
     <li><a href="#architecture">Architecture</a></li>
     <li><a href="#implementation">Implementation</a></li>
     <li><a href="#demo">Live Demo</a></li>
     <li><a href="#integration">Integration</a></li>
     <li><a href="#build">Build</a></li>
   </ul>
   <span class="nbadge">DESIGN SPEC v1.0</span>
 </nav>

 <div class="hero">
   <div class="htag">KNIRVSHELL · PORTABLE DVE · WASM-NATIVE</div>
   <h1>DVE Pod</h1>
   <p class="hsub">A Decentralized Virtual Environment delivered through the <code style="-webkit-text-fill-color:var(--cyan);font-size:.9em">knirv</code> CLI — runs anywhere, trusts nothing it can't prove, and escalates capability as trust is established.</p>
   <div class="hpills">
     <span class="pill pill-cyan">KNIRVSHELL Embedded</span>
     <span class="pill pill-purple">TinyGo + WASI</span>
     <span class="pill pill-green">Auto Runtime Install</span>
     <span class="pill pill-amber">WebCrypto TEE</span>
     <span class="pill pill-cyan">knirv dve pod</span>
     <span class="pill pill-purple">Single-File Bundle</span>
   </div>
 </div>

 <!-- APPROACH -->
 <section id="approach">
   <div class="sec-label">DESIGN DECISION</div>
   <h2>Why This Approach</h2>
   <p class="lead">Three candidate designs were evaluated. The chosen approach — a WASI-native WASM module with a browser JS host and optional CLI runtime — wins on every axis.</p>

   <div class="grid grid-3" style="margin-bottom:2rem">
     <div class="card" style="border-color:rgba(16,185,129,.3);background:rgba(16,185,129,.04)">
       <div class="card-icon">✓</div>
       <h3 style="color:var(--green)">DVE Pod via KNIRVSHELL (chosen)</h3>
       <p>TinyGo → WASM/WASI binary embedded inside the <code>knirv</code> CLI. KNIRVSHELL auto-detects or installs a WASM runtime, then exposes clean <code>knirv dve pod</code> commands — no runtime plumbing visible to the user.</p>
     </div>
     <div class="card" style="opacity:.6">
       <div class="card-icon">✗</div>
       <h3>iFrame Proxy</h3>
       <p>iFrame into a remote KNIRVSERVER DVE. Simple but requires constant network, exposes server URL, no offline capability, no portability — just a thin wrapper.</p>
     </div>
     <div class="card" style="opacity:.6">
       <div class="card-icon">✗</div>
       <h3>Full Go WASM Bundle</h3>
       <p>Compile entire KNIRVSERVER stack to WASM. Binary would be 40MB+, Go WASM runtime overhead is severe, and most server logic (eBPF, SGX, P2P) can't run client-side.</p>
     </div>
   </div>

   <div class="layers">
+    <div class="layer l3">
+      <div class="layer-num">CLI</div>
+      <div class="layer-info">
+        <div class="layer-title">KNIRVSHELL (<code>knirv</code>) — Entry Point</div>
+        <div class="layer-desc">The <code>knirv</code> binary embeds <code>dvepod.wasm</code> via <code>//go:embed</code>. On first <code>knirv dve pod</code> call, it checks for Wasmer/Wasmtime in PATH; if absent, auto-downloads and installs Wasmer. All WASM runtime invocations are internal — users only see <code>knirv</code> commands.</div>
+      </div>
+      <span class="layer-badge pill-purple">primary entry point</span>
+    </div>
     <div class="layer l0">
       <div class="layer-num">L0</div>
       <div class="layer-info">
         <div class="layer-title">WASM Core — Solo Mode</div>
-        <div class="layer-desc">TinyGo-compiled WASM module. BusyBox tools, shell parser, KNIRVAGENT logic, TEE simulation. No network required. Runs offline forever.</div>
+        <div class="layer-desc">TinyGo-compiled WASM module extracted from the <code>knirv</code> binary at runtime. BusyBox tools, shell parser, KNIRVAGENT logic, TEE simulation. No network required. Runs offline.</div>
       </div>
       <span class="layer-badge pill-green">always available</span>
     </div>
     <div class="layer l1">
       <div class="layer-num">L1</div>
       <div class="layer-info">
-        <div class="layer-title">Browser Host — Tethered Mode</div>
-        <div class="layer-desc">JavaScript WASI shim. Maps WASI syscalls → WebCrypto (identity), OPFS (filesystem), fetch() (networking), xterm.js (terminal I/O).</div>
+        <div class="layer-title">Browser Host — HTML Bundle Mode</div>
+        <div class="layer-desc"><code>knirv dve pod bundle</code> generates a self-contained HTML file with the WASM binary base64-inlined. JavaScript WASI shim maps syscalls → WebCrypto, OPFS, xterm.js. Opens in any browser, no server needed.</div>
       </div>
       <span class="layer-badge pill-cyan">browser runtime</span>
     </div>
     <div class="layer l2">
       <div class="layer-num">L2</div>
       <div class="layer-info">
         <div class="layer-title">KNIRVSERVER Bridge — Full DVE Mode</div>
-        <div class="layer-desc">WebSocket tunnel to existing <code>/ws/dve/{nodeId}/agent</code> handler. Inherits full KNIRVAGENT, inner sessions, hardware TEE attestation, on-chain session binding.</div>
+        <div class="layer-desc"><code>knirv dve pod dock &lt;url&gt;</code> opens a WebSocket tunnel to <code>/ws/dve/{nodeId}/agent</code>. Inherits full KNIRVAGENT, inner sessions, hardware TEE attestation, on-chain session binding.</div>
       </div>
       <span class="layer-badge pill-amber">optional, requires network</span>
     </div>
-    <div class="layer l3">
-      <div class="layer-num">L3</div>
-      <div class="layer-info">
-        <div class="layer-title">WASI CLI Runtime — Wasmer / Wasmtime / WasmEdge</div>
-        <div class="layer-desc">Same WASM binary on server or local machine. WASI provides real filesystem, TCP sockets, environment variables. No browser required.</div>
-      </div>
-      <span class="layer-badge pill-purple">cli runtime</span>
-    </div>
   </div>
 </section>

 <!-- ARCHITECTURE -->
 <section id="architecture">
   <div class="sec-label">SYSTEM DESIGN</div>
   <h2>Architecture</h2>
   <p class="lead">The DVE Pod is a layered system where the WASM core is host-agnostic. The host environment (browser JS or WASI runtime) provides I/O, storage, and networking syscalls.</p>

   <div class="arch-wrap">
     <svg viewBox="0 0 880 520" fill="none" xmlns="http://www.w3.org/2000/svg">
       <!-- Background panels -->
       <!-- Browser Host zone -->
       <rect x="10" y="10" width="860" height="500" rx="14" fill="#080f1e" stroke="rgba(0,212,255,0.15)" stroke-width="1"/>

       <!-- WASM Core box (center) -->
       <rect x="295" y="60" width="290" height="340" rx="10" fill="#0d1628" stroke="rgba(0,212,255,0.4)" stroke-width="1.5"/>
       <text x="440" y="88" font-family="monospace" font-size="11" fill="#00d4ff" text-anchor="middle" font-weight="700">WASM CORE (TinyGo)</text>

       <!-- WASM Core components -->
       <rect x="315" y="98" width="115" height="36" rx="6" fill="rgba(0,212,255,0.08)" stroke="rgba(0,212,255,0.25)" stroke-width="1"/>
       <text x="372" y="121" font-family="monospace" font-size="9.5" fill="#00d4ff" text-anchor="middle">KNIRVAGENT</text>

       <rect x="445" y="98" width="115" height="36" rx="6" fill="rgba(124,58,237,0.08)" stroke="rgba(124,58,237,0.25)" stroke-width="1"/>
       <text x="502" y="121" font-family="monospace" font-size="9.5" fill="#a78bfa" text-anchor="middle">Shell Parser</text>

       <rect x="315" y="148" width="115" height="36" rx="6" fill="rgba(16,185,129,0.08)" stroke="rgba(16,185,129,0.25)" stroke-width="1"/>
       <text x="372" y="165" font-family="monospace" font-size="9" fill="#34d399" text-anchor="middle">BusyBox Tools</text>
       <text x="372" y="178" font-family="monospace" font-size="8" fill="#34d399" text-anchor="middle">(20+ commands)</text>

       <rect x="445" y="148" width="115" height="36" rx="6" fill="rgba(245,158,11,0.08)" stroke="rgba(245,158,11,0.25)" stroke-width="1"/>
       <text x="502" y="165" font-family="monospace" font-size="9" fill="#fbbf24" text-anchor="middle">TEE Context</text>
       <text x="502" y="178" font-family="monospace" font-size="8" fill="#fbbf24" text-anchor="middle">(attestation)</text>

       <rect x="315" y="198" width="245" height="36" rx="6" fill="rgba(239,68,68,0.06)" stroke="rgba(239,68,68,0.2)" stroke-width="1"/>
       <text x="437" y="221" font-family="monospace" font-size="9.5" fill="#f87171" text-anchor="middle">Storage Layer (WASI FS API)</text>

       <rect x="315" y="248" width="245" height="36" rx="6" fill="rgba(255,255,255,0.03)" stroke="rgba(255,255,255,0.1)" stroke-width="1"/>
       <text x="437" y="271" font-family="monospace" font-size="9.5" fill="#94a3b8" text-anchor="middle">Network Adapter (WASI sockets)</text>

       <!-- Trust levels -->
       <rect x="315" y="298" width="115" height="36" rx="6" fill="rgba(0,212,255,0.05)" stroke="rgba(0,212,255,0.15)" stroke-width="1"/>
       <text x="372" y="315" font-family="monospace" font-size="9" fill="#7dd3fc" text-anchor="middle">Identity</text>
       <text x="372" y="328" font-family="monospace" font-size="8" fill="#7dd3fc" text-anchor="middle">(P-256 keypair)</text>

       <rect x="445" y="298" width="115" height="36" rx="6" fill="rgba(124,58,237,0.05)" stroke="rgba(124,58,237,0.15)" stroke-width="1"/>
       <text x="502" y="315" font-family="monospace" font-size="9" fill="#c4b5fd" text-anchor="middle">Session Mgr</text>
       <text x="502" y="328" font-family="monospace" font-size="8" fill="#c4b5fd" text-anchor="middle">(chain binding)</text>

       <!-- WASM label bottom -->
       <text x="440" y="385" font-family="monospace" font-size="9" fill="rgba(0,212,255,0.4)" text-anchor="middle">dvepod.wasm  ·  ~3MB TinyGo binary</text>

       <!-- LEFT: Browser Host -->
       <rect x="24" y="60" width="258" height="340" rx="10" fill="rgba(0,212,255,0.02)" stroke="rgba(0,212,255,0.2)" stroke-width="1" stroke-dasharray="5,3"/>
       <text x="153" y="82" font-family="monospace" font-size="10" fill="rgba(0,212,255,0.7)" text-anchor="middle">BROWSER HOST (JS)</text>

       <rect x="40" y="95" width="225" height="32" rx="6" fill="rgba(0,212,255,0.06)" stroke="rgba(0,212,255,0.2)" stroke-width="1"/>
       <text x="152" y="115" font-family="monospace" font-size="9.5" fill="#00d4ff" text-anchor="middle">xterm.js Terminal</text>

       <rect x="40" y="140" width="225" height="32" rx="6" fill="rgba(0,212,255,0.06)" stroke="rgba(0,212,255,0.2)" stroke-width="1"/>
       <text x="152" y="160" font-family="monospace" font-size="9.5" fill="#00d4ff" text-anchor="middle">WASI Shim (stdin/stdout/fs)</text>

       <rect x="40" y="185" width="107" height="32" rx="6" fill="rgba(16,185,129,0.06)" stroke="rgba(16,185,129,0.2)" stroke-width="1"/>
       <text x="93" y="205" font-family="monospace" font-size="9" fill="#34d399" text-anchor="middle">WebCrypto TEE</text>

       <rect x="157" y="185" width="108" height="32" rx="6" fill="rgba(16,185,129,0.06)" stroke="rgba(16,185,129,0.2)" stroke-width="1"/>
       <text x="211" y="205" font-family="monospace" font-size="9" fill="#34d399" text-anchor="middle">OPFS Storage</text>

       <rect x="40" y="230" width="225" height="32" rx="6" fill="rgba(245,158,11,0.06)" stroke="rgba(245,158,11,0.2)" stroke-width="1"/>
