     <div id="tab-wasm" class="tab-pane active">
 <pre><span class="cm">// cmd/dvepod/main.go — TinyGo WASI entrypoint
 // Build: tinygo build -target=wasi -o dvepod.wasm ./cmd/dvepod/
 // Run browser: open dvepod.html
 // Run CLI:     wasmer run dvepod.wasm</span>

 <span class="kw">package</span> main

 <span class="kw">import</span> (
     <span class="str">"bufio"</span>
     <span class="str">"fmt"</span>
     <span class="str">"os"</span>
     <span class="str">"strings"</span>

     <span class="str">"github.com/knirv/dvepod/internal/agent"</span>
     <span class="str">"github.com/knirv/dvepod/internal/shell"</span>
     <span class="str">"github.com/knirv/dvepod/internal/tee"</span>
     <span class="str">"github.com/knirv/dvepod/internal/tools"</span>
 )

 <span class="kw">func</span> <span class="fn">main</span>() {
     ctx, _ := tee.<span class="fn">NewContext</span>()    <span class="cm">// generates P-256 identity, measures WASM hash</span>
     bb  := tools.<span class="fn">NewBusyBox</span>(ctx)   <span class="cm">// registers 20+ BusyBox commands</span>
     ag  := agent.<span class="fn">New</span>(ctx)           <span class="cm">// KNIRVAGENT: solo by default, upgrades on dock</span>
     sh  := shell.<span class="fn">New</span>(ctx, bb, ag)   <span class="cm">// line-editing shell with history</span>

     sh.<span class="fn">Boot</span>()                        <span class="cm">// print boot banner, perform self-attestation</span>

     scanner := bufio.<span class="fn">NewScanner</span>(os.Stdin)
     <span class="kw">for</span> {
         fmt.<span class="fn">Fprint</span>(os.Stdout, sh.<span class="fn">Prompt</span>())
         <span class="kw">if</span> !scanner.<span class="fn">Scan</span>() { <span class="kw">break</span> }
         sh.<span class="fn">Exec</span>(scanner.<span class="fn">Text</span>())
     }
 }

 <span class="cm">// internal/shell/shell.go — command dispatcher</span>
 <span class="kw">type</span> <span class="ty">Shell</span> <span class="kw">struct</span> {
     ctx     *tee.<span class="ty">Context</span>
     bb      *tools.<span class="ty">BusyBox</span>
     agent   *agent.<span class="ty">KNIRVAgent</span>
     cwd     <span class="ty">string</span>
     history []<span class="ty">string</span>
     env     <span class="kw">map</span>[<span class="ty">string</span>]<span class="ty">string</span>
     mode    <span class="ty">string</span>   <span class="cm">// "solo" | "tethered" | "bridged"</span>
     dockURL <span class="ty">string</span>
 }

 <span class="kw">func</span> (s *<span class="ty">Shell</span>) <span class="fn">Exec</span>(line <span class="ty">string</span>) {
     line = strings.<span class="fn">TrimSpace</span>(line)
     <span class="kw">if</span> line == <span class="str">""</span> { <span class="kw">return</span> }
     s.history = <span class="fn">append</span>(s.history, line)

     parts := shell.<span class="fn">ParseLine</span>(line)    <span class="cm">// handles quotes, escapes, pipes</span>
     cmd, args := parts[<span class="num">0</span>], parts[<span class="num">1</span>:]

     <span class="kw">switch</span> cmd {
     <span class="cm">// BusyBox built-ins</span>
     <span class="kw">case</span> <span class="str">"ls"</span>, <span class="str">"cat"</span>, <span class="str">"echo"</span>, <span class="str">"mkdir"</span>, <span class="str">"rm"</span>, <span class="str">"cp"</span>, <span class="str">"mv"</span>,
          <span class="str">"env"</span>, <span class="str">"pwd"</span>, <span class="str">"ps"</span>, <span class="str">"curl"</span>, <span class="str">"grep"</span>, <span class="str">"wc"</span>, <span class="str">"find"</span>,
          <span class="str">"chmod"</span>, <span class="str">"whoami"</span>, <span class="str">"date"</span>, <span class="str">"df"</span>, <span class="str">"free"</span>, <span class="str">"uname"</span>:
         out, err := s.bb.<span class="fn">Run</span>(cmd, args, s.cwd, s.env)
         s.<span class="fn">print</span>(out, err)

     <span class="cm">// DVE-specific commands</span>
     <span class="kw">case</span> <span class="str">"tee"</span>:   s.<span class="fn">cmdTEE</span>(args)
     <span class="kw">case</span> <span class="str">"agent"</span>: s.<span class="fn">cmdAgent</span>(args)
     <span class="kw">case</span> <span class="str">"dock"</span>:  s.<span class="fn">cmdDock</span>(args)
     <span class="kw">case</span> <span class="str">"net"</span>:   s.<span class="fn">cmdNet</span>(args)
     <span class="kw">case</span> <span class="str">"nrn"</span>:   s.<span class="fn">cmdNRN</span>(args)
     <span class="kw">case</span> <span class="str">"export"</span>:s.<span class="fn">cmdExport</span>(args)
     <span class="kw">case</span> <span class="str">"help"</span>:  s.<span class="fn">cmdHelp</span>()
     <span class="kw">case</span> <span class="str">"clear"</span>: fmt.<span class="fn">Print</span>(<span class="str">"\033[2J\033[H"</span>)
     <span class="kw">default</span>:
         fmt.<span class="fn">Fprintf</span>(os.Stderr, <span class="str">"dvepod: %s: command not found\n"</span>, cmd)
     }
 }

 <span class="kw">func</span> (s *<span class="ty">Shell</span>) <span class="fn">cmdDock</span>(args []<span class="ty">string</span>) {
     <span class="kw">if</span> len(args) == <span class="num">0</span> {
         fmt.<span class="fn">Println</span>(<span class="str">"usage: dock &lt;knirvserver-url&gt; [--node-id &lt;id&gt;]"</span>)
         <span class="kw">return</span>
     }
     s.dockURL = args[<span class="num">0</span>]
     s.agent.<span class="fn">SetEndpoint</span>(s.dockURL)   <span class="cm">// upgrades from solo → tethered</span>
     s.mode = <span class="str">"tethered"</span>

     <span class="cm">// Present our attestation to the server, get a chain session ID</span>
     att, _ := s.ctx.<span class="fn">Attest</span>()
     sid, err := s.agent.<span class="fn">Register</span>(att)
     <span class="kw">if</span> err != nil {
         fmt.<span class="fn">Printf</span>(<span class="str">"\033[31m✗ dock failed: %v\033[0m\n"</span>, err)
         <span class="kw">return</span>
     }
     s.env[<span class="str">"CHAIN_SESSION_ID"</span>] = sid
     s.mode = <span class="str">"bridged"</span>
     fmt.<span class="fn">Printf</span>(<span class="str">"\033[32m✓ docked to %s (session: %s)\033[0m\n"</span>, args[<span class="num">0</span>], sid[:<span class="num">12</span>])
 }</pre>
     </div>

     <div id="tab-bridge" class="tab-pane">
 <pre><span class="cm">// dvepod-host.js — WASI browser host (inlined in dvepod.html)
 // Bridges WASM WASI syscalls to browser APIs.</span>

 <span class="kw">class</span> <span class="ty">DVEPodHost</span> {
   <span class="kw">constructor</span>(terminal) {
     <span class="kw">this</span>.term     = terminal;        <span class="cm">// xterm.js Terminal instance</span>
     <span class="kw">this</span>.opfs     = <span class="kw">null</span>;            <span class="cm">// Origin Private File System root</span>
     <span class="kw">this</span>.stdinBuf = <span class="str">''</span>;             <span class="cm">// line buffer from xterm input</span>
     <span class="kw">this</span>.stdinRes = <span class="kw">null</span>;           <span class="cm">// pending stdin Promise resolver</span>
     <span class="kw">this</span>.decoder  = <span class="kw">new</span> TextDecoder();
     <span class="kw">this</span>.encoder  = <span class="kw">new</span> TextEncoder();
   }

   <span class="kw">async</span> <span class="fn">init</span>() {
     <span class="cm">// Acquire OPFS root — persistent, quota-managed, sandboxed</span>
     <span class="kw">this</span>.opfs = <span class="kw">await</span> navigator.storage.<span class="fn">getDirectory</span>();
     <span class="kw">await this</span>.<span class="fn">ensureDir</span>(<span class="str">'home/dvepod'</span>);
     <span class="kw">await this</span>.<span class="fn">ensureDir</span>(<span class="str">'home/dvepod/.knirv'</span>);
     <span class="kw">await this</span>.<span class="fn">ensureDir</span>(<span class="str">'home/dvepod/workspace'</span>);
     <span class="kw">await this</span>.<span class="fn">ensureDir</span>(<span class="str">'var/run/knirv'</span>);
     <span class="kw">await this</span>.<span class="fn">ensureDir</span>(<span class="str">'tmp'</span>);

     <span class="kw">return this</span>.<span class="fn">wasiImports</span>();     <span class="cm">// pass to WebAssembly.instantiate</span>
   }

   <span class="fn">wasiImports</span>() {
     <span class="kw">return</span> {
       wasi_snapshot_preview1: {
         <span class="cm">// stdout → xterm.js</span>
         <span class="fn">fd_write</span>: (fd, iovs, iovsLen, nwritten) => {
           <span class="kw">if</span> (fd !== <span class="num">1</span> && fd !== <span class="num">2</span>) <span class="kw">return</span> <span class="num">8</span>;
           <span class="kw">const</span> view = <span class="kw">new</span> DataView(<span class="kw">this</span>.memory.buffer);
           <span class="kw">let</span> written = <span class="num">0</span>;
           <span class="kw">for</span> (<span class="kw">let</span> i = <span class="num">0</span>; i < iovsLen; i++) {
             <span class="kw">const</span> ptr = view.<span class="fn">getUint32</span>(iovs + i * <span class="num">8</span>, <span class="kw">true</span>);
             <span class="kw">const</span> len = view.<span class="fn">getUint32</span>(iovs + i * <span class="num">8</span> + <span class="num">4</span>, <span class="kw">true</span>);
             <span class="kw">const</span> bytes = <span class="kw">new</span> Uint8Array(<span class="kw">this</span>.memory.buffer, ptr, len);
             <span class="kw">this</span>.term.<span class="fn">write</span>(<span class="kw">this</span>.decoder.<span class="fn">decode</span>(bytes));
             written += len;
           }
           view.<span class="fn">setUint32</span>(nwritten, written, <span class="kw">true</span>);
           <span class="kw">return</span> <span class="num">0</span>;
         },

         <span class="cm">// stdin ← xterm.js keystrokes (line-buffered)</span>
         <span class="fn">fd_read</span>: (fd, iovs, iovsLen, nread) => {
           <span class="cm">// Returns EAGAIN; real input pumped via SharedArrayBuffer or postMessage</span>
           <span class="kw">return</span> <span class="num">6</span>; <span class="cm">// EAGAIN — async model handled via Atomics.wait</span>
         },

         <span class="cm">// OPFS-backed filesystem ops</span>
         <span class="fn">path_open</span>:   (...args) => <span class="kw">this</span>.<span class="fn">opfsOpen</span>(...args),
         <span class="fn">fd_close</span>:    (fd)      => <span class="kw">this</span>.<span class="fn">opfsClose</span>(fd),
         <span class="fn">path_create_directory</span>: (...a) => <span class="kw">this</span>.<span class="fn">opfsMkdir</span>(...a),
         <span class="fn">path_filestat_get</span>:     (...a) => <span class="kw">this</span>.<span class="fn">opfsStat</span>(...a),

         <span class="cm">// Environment</span>
         <span class="fn">environ_sizes_get</span>: (countPtr, sizePtr) => <span class="kw">this</span>.<span class="fn">envSizes</span>(countPtr, sizePtr),
         <span class="fn">environ_get</span>: (envPtr, bufPtr)           => <span class="kw">this</span>.<span class="fn">envGet</span>(envPtr, bufPtr),

         <span class="cm">// Randomness (WebCrypto → WASM)</span>
         <span class="fn">random_get</span>: (bufPtr, bufLen) => {
           <span class="kw">const</span> buf = <span class="kw">new</span> Uint8Array(<span class="kw">this</span>.memory.buffer, bufPtr, bufLen);
           crypto.<span class="fn">getRandomValues</span>(buf);
           <span class="kw">return</span> <span class="num">0</span>;
         },

         <span class="fn">proc_exit</span>: (code) => { <span class="kw">throw new</span> WebAssembly.RuntimeError(<span class="str">`exit(${code})`</span>); },
         <span class="fn">clock_time_get</span>: (id, prec, timePtr) => {
           <span class="kw">const</span> view = <span class="kw">new</span> DataView(<span class="kw">this</span>.memory.buffer);
           view.<span class="fn">setBigUint64</span>(timePtr, BigInt(Date.<span class="fn">now</span>()) * <span class="num">1000000n</span>, <span class="kw">true</span>);
           <span class="kw">return</span> <span class="num">0</span>;
         },
       }
     };
   }

   <span class="cm">// Feed xterm keystrokes into WASM stdin via SharedArrayBuffer</span>
   <span class="fn">feedStdin</span>(data) {
     <span class="kw">this</span>.stdinBuf += data;
     <span class="kw">if</span> (<span class="kw">this</span>.stdinRes && <span class="kw">this</span>.stdinBuf.<span class="fn">includes</span>(<span class="str">'\n'</span>)) {
       <span class="kw">const</span> res = <span class="kw">this</span>.stdinRes;
       <span class="kw">this</span>.stdinRes = <span class="kw">null</span>;
       res();
     }
   }
 }</pre>
