     <div id="tab-tee" class="tab-pane">
 <pre><span class="cm">// internal/tee/tee.go — TEE simulation layer
 // Browser mode:  P-256 keypair via WebCrypto (WASM interop call)
 // SGX mode:      real quote generation via go-sgx-quote library
 // SNP mode:      AMD SEV attestation via /dev/sev-guest
 // Wasmer mode:   software attestation (WASM binary hash + host fingerprint)</span>

 <span class="kw">package</span> tee

 <span class="kw">import</span> (
     <span class="str">"crypto/rand"</span>
     <span class="str">"crypto/sha256"</span>
     <span class="str">"encoding/hex"</span>
     <span class="str">"encoding/json"</span>
     <span class="str">"os"</span>
     <span class="str">"time"</span>
 )

 <span class="kw">type</span> <span class="ty">Context</span> <span class="kw">struct</span> {
     NodeID      <span class="ty">string</span>    <span class="cm">`json:"node_id"`</span>
     TEEType     <span class="ty">string</span>    <span class="cm">`json:"tee_type"`</span>      <span class="cm">// browser-wasm|wasmer|sgx|sev-snp|tdx</span>
     WASMHash    <span class="ty">string</span>    <span class="cm">`json:"wasm_hash"`</span>     <span class="cm">// SHA-256 of this exact binary</span>
     PublicKey   []<span class="ty">byte</span>    <span class="cm">`json:"public_key"`</span>
     Measurement <span class="ty">string</span>    <span class="cm">`json:"measurement"`</span>   <span class="cm">// TEE PCR equivalent</span>
     CreatedAt   time.<span class="ty">Time</span> <span class="cm">`json:"created_at"`</span>
 }

 <span class="kw">func</span> <span class="fn">NewContext</span>() (*<span class="ty">Context</span>, <span class="ty">error</span>) {
     <span class="cm">// Measure this WASM binary — proves integrity of the runtime</span>
     wasmBytes, _ := os.<span class="fn">ReadFile</span>(<span class="str">"/proc/self/exe"</span>)
     hash := sha256.<span class="fn">Sum256</span>(wasmBytes)

     <span class="cm">// Generate ephemeral identity or load persisted keypair</span>
     nodeIDBytes := make([]<span class="ty">byte</span>, <span class="num">16</span>)
     rand.<span class="fn">Read</span>(nodeIDBytes)

     ctx := &<span class="ty">Context</span>{
         NodeID:      <span class="str">"dvepod-"</span> + hex.<span class="fn">EncodeToString</span>(nodeIDBytes[:<span class="num">8</span>]),
         TEEType:     <span class="fn">detectTEEType</span>(),
         WASMHash:    hex.<span class="fn">EncodeToString</span>(hash[:]),
         Measurement: <span class="fn">deriveMeasurement</span>(hash[:]),
         CreatedAt:   time.<span class="fn">Now</span>(),
     }
     ctx.PublicKey = <span class="fn">generateOrLoadKey</span>(ctx.NodeID)
     <span class="kw">return</span> ctx, <span class="kw">nil</span>
 }

 <span class="kw">func</span> (c *<span class="ty">Context</span>) <span class="fn">Attest</span>() (<span class="ty">Attestation</span>, <span class="ty">error</span>) {
     payload := <span class="kw">map</span>[<span class="ty">string</span>]<span class="kw">interface</span>{}{
         <span class="str">"node_id"</span>:     c.NodeID,
         <span class="str">"tee_type"</span>:    c.TEEType,
         <span class="str">"wasm_hash"</span>:   c.WASMHash,
         <span class="str">"measurement"</span>: c.Measurement,
         <span class="str">"public_key"</span>:  hex.<span class="fn">EncodeToString</span>(c.PublicKey),
         <span class="str">"timestamp"</span>:   time.<span class="fn">Now</span>().<span class="fn">Unix</span>(),
         <span class="str">"version"</span>:     <span class="str">"dvepod/1.0"</span>,
     }
     data, _ := json.<span class="fn">Marshal</span>(payload)
     sig := <span class="fn">sign</span>(data, c.NodeID)   <span class="cm">// ECDSA P-256 signature via JS interop (browser)</span>
                                     <span class="cm">// or crypto/ecdsa (WASI CLI)</span>
     <span class="kw">return</span> <span class="ty">Attestation</span>{Payload: payload, Signature: sig}, <span class="kw">nil</span>
 }

 <span class="cm">// Server-side verification: packages/KNIRVSERVER/backend/internal/web/dve_pod_handler.go</span>
 <span class="cm">// POST /api/dve/pod/register  →  validates attestation, creates lightweight DVECreation</span>
 <span class="kw">func</span> <span class="fn">VerifyPodAttestation</span>(att <span class="ty">Attestation</span>) <span class="ty">error</span> {
     <span class="cm">// 1. Verify signature against claimed public key</span>
     <span class="cm">// 2. Check wasm_hash against known good hashes (registry)</span>
     <span class="cm">// 3. For tee_type=sgx: forward to Intel Attestation Service</span>
     <span class="cm">// 4. For tee_type=browser-wasm: accept with reduced trust level (L1 only)</span>
     <span class="cm">// 5. Issue chain session ID → return to pod</span>
     <span class="kw">return</span> verifyECDSA(att.Payload, att.Signature)
 }</pre>
     </div>

     <div id="tab-storage" class="tab-pane">
 <pre><span class="cm">// Storage architecture: three-tier persistence
 //
 // Tier 1: OPFS (Origin Private File System)
 //   - Exposed to WASM as virtual WASI filesystem
 //   - Persistent across browser sessions, up to browser storage quota
 //   - Directory: /home/dvepod/, /var/run/knirv/, /tmp/
 //   - Used for: workspace files, config, agent artifacts
 //
 // Tier 2: IndexedDB (structured data)
 //   - Command history, agent chat history, session metadata
 //   - Key: dvepod-{nodeId}-{table}
 //   - Not exposed to WASM directly; accessed via JS bridge call
 //
 // Tier 3: In-memory (WASM linear memory)
 //   - Active process state, environment variables, pipe buffers
 //   - Lost on page reload; bootstrapped from Tier 1 on startup

 <span class="cm">// internal/storage/storage.go — WASI filesystem operations</span>
 <span class="kw">package</span> storage

 <span class="kw">import</span> (
     <span class="str">"encoding/json"</span>
     <span class="str">"os"</span>
     <span class="str">"path/filepath"</span>
 )

 <span class="kw">const</span> BaseDir = <span class="str">"/home/dvepod/.knirv"</span>

 <span class="kw">func</span> <span class="fn">SaveIdentity</span>(nodeID <span class="ty">string</span>, pubKey []<span class="ty">byte</span>) <span class="ty">error</span> {
     path := filepath.<span class="fn">Join</span>(BaseDir, <span class="str">"identity.json"</span>)
     data, _ := json.<span class="fn">Marshal</span>(<span class="kw">map</span>[<span class="ty">string</span>]<span class="kw">interface</span>{}{
         <span class="str">"node_id"</span>:    nodeID,
         <span class="str">"public_key"</span>: pubKey,
         <span class="str">"created_at"</span>: <span class="fn">nowISO</span>(),
     })
     <span class="kw">return</span> os.<span class="fn">WriteFile</span>(path, data, <span class="num">0600</span>)
 }

 <span class="kw">func</span> <span class="fn">SaveAttestation</span>(att <span class="kw">interface</span>{}) <span class="ty">error</span> {
     path := filepath.<span class="fn">Join</span>(BaseDir, <span class="str">"attestation.json"</span>)
     data, _ := json.<span class="fn">MarshalIndent</span>(att, <span class="str">""</span>, <span class="str">"  "</span>)
     <span class="kw">return</span> os.<span class="fn">WriteFile</span>(path, data, <span class="num">0644</span>)
 }

 <span class="kw">func</span> <span class="fn">SaveSession</span>(chainSessionID <span class="ty">string</span>) <span class="ty">error</span> {
     path := filepath.<span class="fn">Join</span>(BaseDir, <span class="str">"session.json"</span>)
     data, _ := json.<span class="fn">Marshal</span>(<span class="kw">map</span>[<span class="ty">string</span>]<span class="ty">string</span>{
         <span class="str">"chain_session_id"</span>: chainSessionID,
         <span class="str">"saved_at"</span>:         <span class="fn">nowISO</span>(),
     })
     <span class="kw">return</span> os.<span class="fn">WriteFile</span>(path, data, <span class="num">0600</span>)
 }

 <span class="cm">// Encrypted export: packages entire OPFS tree as AES-256-GCM encrypted tarball
 // Key derived from pod's P-256 private key via ECDH + HKDF
 // Allows moving a DVE Pod to a new browser / machine</span>
 <span class="kw">func</span> <span class="fn">ExportPod</span>(nodeID, destPath <span class="ty">string</span>) <span class="ty">error</span> {
     <span class="cm">// 1. tar -czf /tmp/dvepod-export.tar.gz /home/dvepod/</span>
     <span class="cm">// 2. Encrypt with AES-256-GCM using pod's derived key</span>
     <span class="cm">// 3. Write to destPath + print decryption instructions</span>
     <span class="kw">return</span> <span class="fn">encryptedTar</span>(BaseDir, destPath, nodeID)
 }</pre>
     </div>

     <div id="tab-server" class="tab-pane">
 <pre><span class="cm">// packages/KNIRVSERVER/backend/internal/web/dve_pod_handler.go
 // New handler: mounts alongside existing DVE handlers with minimal surface area.
 // Existing WebSocket handlers work unchanged — pods dock to them directly.</span>

 <span class="kw">package</span> web

 <span class="kw">import</span> (
     <span class="str">"encoding/json"</span>
     <span class="str">"net/http"</span>
     <span class="str">"github.com/knirv/knirvserver/backend/internal/objects"</span>
     <span class="str">"github.com/knirv/knirvserver/backend/internal/tee"</span>
 )

 <span class="cm">// New routes to add in route registration:</span>
 <span class="cm">//   POST /api/dve/pod/register   → RegisterPod</span>
 <span class="cm">//   GET  /api/dve/pod/{nodeId}/bundle  → DownloadPodBundle</span>
 <span class="cm">//   POST /api/dve/pod/{nodeId}/attest  → UpgradeAttestation</span>
 <span class="cm">//</span>
 <span class="cm">// Pods then connect to EXISTING endpoints:</span>
 <span class="cm">//   WS /ws/dve/{nodeId}/agent           (supervisor terminal)</span>
 <span class="cm">//   WS /ws/dve/{dveId}/inner/{sessionId} (inner tool sessions)</span>

 <span class="kw">type</span> <span class="ty">PodRegistrationRequest</span> <span class="kw">struct</span> {
     Attestation tee.<span class="ty">Attestation</span> <span class="cm">`json:"attestation"`</span>
     Name        <span class="ty">string</span>          <span class="cm">`json:"name"`</span>
     OwnerID     <span class="ty">string</span>          <span class="cm">`json:"owner_id"`</span>   <span class="cm">// from auth header</span>
 }

 <span class="kw">type</span> <span class="ty">PodRegistrationResponse</span> <span class="kw">struct</span> {
     NodeID         <span class="ty">string</span> <span class="cm">`json:"node_id"`</span>
     ChainSessionID <span class="ty">string</span> <span class="cm">`json:"chain_session_id"`</span>
     AgentWSURL     <span class="ty">string</span> <span class="cm">`json:"agent_ws_url"`</span>      <span class="cm">// /ws/dve/{nodeId}/agent</span>
     TrustLevel     <span class="ty">int</span>    <span class="cm">`json:"trust_level"`</span>       <span class="cm">// 1=browser, 2=wasi, 3=sgx</span>
     Capabilities   []<span class="ty">string</span> <span class="cm">`json:"capabilities"`</span>
 }

 <span class="kw">func</span> (h *<span class="ty">DVEPodHandler</span>) <span class="fn">RegisterPod</span>(w http.<span class="ty">ResponseWriter</span>, r *http.<span class="ty">Request</span>) {
     <span class="kw">var</span> req <span class="ty">PodRegistrationRequest</span>
     <span class="kw">if</span> err := json.<span class="fn">NewDecoder</span>(r.Body).<span class="fn">Decode</span>(&req); err != <span class="kw">nil</span> {
         http.<span class="fn">Error</span>(w, err.<span class="fn">Error</span>(), http.StatusBadRequest)
         <span class="kw">return</span>
     }

     <span class="cm">// Verify attestation signature</span>
     trustLevel, err := tee.<span class="fn">VerifyPodAttestation</span>(req.Attestation)
     <span class="kw">if</span> err != <span class="kw">nil</span> {
         http.<span class="fn">Error</span>(w, <span class="str">"invalid attestation"</span>, http.StatusUnauthorized)
         <span class="kw">return</span>
     }

     <span class="cm">// Create lightweight DVECreation (no hardware provisioning needed)</span>
     creation := objects.<span class="ty">DVECreation</span>{
         Name:       req.Name,
         OwnerID:    req.OwnerID,
         TEEType:    req.Attestation.TEEType,
         Status:     <span class="str">"active"</span>,
         Persistent: <span class="kw">false</span>,    <span class="cm">// pods are ephemeral by default</span>
     }
     nodeID, _ := h.dveManager.<span class="fn">RegisterPodNode</span>(creation, req.Attestation)

     resp := <span class="ty">PodRegistrationResponse</span>{
         NodeID:         nodeID,
         ChainSessionID: <span class="fn">newChainSession</span>(nodeID),
         AgentWSURL:     <span class="str">"/ws/dve/"</span> + nodeID + <span class="str">"/agent"</span>,
         TrustLevel:     trustLevel,
         Capabilities:   <span class="fn">capsForTrustLevel</span>(trustLevel),
     }
     json.<span class="fn">NewEncoder</span>(w).<span class="fn">Encode</span>(resp)
 }

 <span class="cm">// DownloadPodBundle: generates a signed dvepod.html bundle on demand.
 // The HTML file has the WASM binary base64-inlined and the node's
 // config pre-seeded so the user opens it and is immediately connected.</span>
 <span class="kw">func</span> (h *<span class="ty">DVEPodHandler</span>) <span class="fn">DownloadPodBundle</span>(w http.<span class="ty">ResponseWriter</span>, r *http.<span class="ty">Request</span>) {
     nodeID := r.<span class="fn">PathValue</span>(<span class="str">"nodeId"</span>)
     html := h.bundler.<span class="fn">Generate</span>(nodeID)   <span class="cm">// inlines wasm + config into HTML template</span>
     w.<span class="fn">Header</span>().<span class="fn">Set</span>(<span class="str">"Content-Type"</span>, <span class="str">"text/html"</span>)
     w.<span class="fn">Header</span>().<span class="fn">Set</span>(<span class="str">"Content-Disposition"</span>, <span class="str">`attachment; filename="dvepod-`</span>+nodeID[:<span class="num">8</span>]+<span class="str">`.html"`</span>)
     w.<span class="fn">Write</span>(html)
 }</pre>
     </div>
   </div>
 </section>

