   // --- Terminal output helpers ---
   const c = {
     reset: '\x1b[0m', bold: '\x1b[1m', dim: '\x1b[2m',
     cyan: '\x1b[36m', bcyan: '\x1b[96m', green: '\x1b[32m', bgreen: '\x1b[92m',
     yellow: '\x1b[33m', byellow: '\x1b[93m', red: '\x1b[31m', bred: '\x1b[91m',
     blue: '\x1b[34m', bblue: '\x1b[94m', purple: '\x1b[35m', bpurple: '\x1b[95m',
     gray: '\x1b[90m', white: '\x1b[97m',
   };

   function ansiToHtml(s) {
     const map = {
       '0':'color:inherit;font-weight:normal;opacity:1',
       '1':'font-weight:700','2':'opacity:.5',
       '31':'color:#f87171','91':'color:#fca5a5',
       '32':'color:#4ade80','92':'color:#86efac',
       '33':'color:#facc15','93':'color:#fde68a',
       '34':'color:#60a5fa','94':'color:#93c5fd',
       '35':'color:#c084fc','95':'color:#d8b4fe',
       '36':'color:#22d3ee','96':'color:#67e8f9',
       '37':'color:#e2e8f0','97':'color:#f8fafc',
       '90':'color:#475569',
     };
     return s
       .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
       .replace(/\x1b\[([0-9;]+)m/g, (_, codes) => {
         const style = codes.split(';').map(c => map[c]||'').filter(Boolean).join(';');
         return style ? `</span><span style="${style}">` : '</span><span>';
       });
   }

   function write(text) {
     const lines = text.split('\n');
     lines.forEach((line, i) => {
       if (i > 0) term.appendChild(document.createElement('br'));
       const span = document.createElement('span');
       span.innerHTML = '<span>' + ansiToHtml(line) + '</span>';
       term.appendChild(span);
     });
     term.scrollTop = term.scrollHeight;
   }

   function writeln(text='') { write(text + '\n'); }

