package identitybridge

import (
	"fmt"
	"sync"
	"time"

	"github.com/google/uuid"
)

type TrustLevel string

const (
	TrustLevelNone       TrustLevel = "none"
	TrustLevelLow        TrustLevel = "low"
	TrustLevelMedium     TrustLevel = "medium"
	TrustLevelHigh       TrustLevel = "high"
	TrustLevelMaximum    TrustLevel = "maximum"
)

type IdentitySource string

const (
	IdentitySourceKNIRV   IdentitySource = "knirv"
	IdentitySourceAGT     IdentitySource = "agt"
	IdentitySourceDID     IdentitySource = "did"
	IdentitySourceOIDC    IdentitySource = "oidc"
	IdentitySourceX509    IdentitySource = "x509"
)

type TrustEnvelope struct {
	IdentityID    string            `json:"identity_id"`
	Source        IdentitySource    `json:"source"`
	NodeID        string            `json:"node_id"`
	AgentID       string            `json:"agent_id,omitempty"`
	TrustLevel    TrustLevel        `json:"trust_level"`
	TrustScore    float64           `json:"trust_score"`
	Metadata      map[string]string `json:"metadata,omitempty"`
	Capabilities  []string          `json:"capabilities,omitempty"`
	IssuedAt      time.Time         `json:"issued_at"`
	ExpiresAt     time.Time         `json:"expires_at"`
	Signature     string            `json:"signature,omitempty"`
	Federated     bool              `json:"federated"`
	FederationID  string            `json:"federation_id,omitempty"`
}

type IdentityAttributes struct {
	NodeID       string            `json:"node_id"`
	AgentID      string            `json:"agent_id,omitempty"`
	Roles        []string          `json:"roles,omitempty"`
	Permissions  []string          `json:"permissions,omitempty"`
	Environment  string            `json:"environment"`
	Labels       map[string]string `json:"labels,omitempty"`
	Stake        float64           `json:"stake,omitempty"`
	Reputation   float64           `json:"reputation,omitempty"`
	TEEType      string            `json:"tee_type,omitempty"`
	GeoRegion    string            `json:"geo_region,omitempty"`
}

type TrustMapping struct {
	InternalID      string    `json:"internal_id"`
	ExternalID      string    `json:"external_id"`
	ExternalSource  string    `json:"external_source"`
	MappingType     string    `json:"mapping_type"`
	MappedAt        time.Time `json:"mapped_at"`
	LastVerifiedAt  time.Time `json:"last_verified_at"`
	MappingMetadata map[string]string `json:"mapping_metadata,omitempty"`
}

type IdentityBridge struct {
	mu           sync.RWMutex
	envelopes    map[string]*TrustEnvelope
	mappings     map[string]*TrustMapping
	attributes   map[string]*IdentityAttributes
	defaultTTL   time.Duration
}

func NewIdentityBridge() *IdentityBridge {
	return &IdentityBridge{
		envelopes:  make(map[string]*TrustEnvelope),
		mappings:   make(map[string]*TrustMapping),
		attributes: make(map[string]*IdentityAttributes),
		defaultTTL: 24 * time.Hour,
	}
}

func (ib *IdentityBridge) SetDefaultTTL(ttl time.Duration) {
	ib.mu.Lock()
	defer ib.mu.Unlock()
	ib.defaultTTL = ttl
}

func (ib *IdentityBridge) CreateEnvelope(nodeID, agentID string, source IdentitySource, attrs *IdentityAttributes) *TrustEnvelope {
	ib.mu.Lock()
	defer ib.mu.Unlock()

	if attrs == nil {
		attrs = &IdentityAttributes{
			NodeID:      nodeID,
			Environment: "unknown",
		}
	}

	trustScore := ib.calculateTrustScore(attrs)
	trustLevel := ib.scoreToLevel(trustScore)

	env := &TrustEnvelope{
		IdentityID:   uuid.New().String(),
		Source:       source,
		NodeID:       nodeID,
		AgentID:      agentID,
		TrustLevel:   trustLevel,
		TrustScore:   trustScore,
		Metadata:     make(map[string]string),
		Capabilities: make([]string, 0),
		IssuedAt:     time.Now().UTC(),
		ExpiresAt:    time.Now().UTC().Add(ib.defaultTTL),
		Federated:    false,
	}

	ib.envelopes[env.IdentityID] = env
	ib.attributes[env.IdentityID] = attrs
	return env
}

func (ib *IdentityBridge) GetEnvelope(identityID string) (*TrustEnvelope, bool) {
	ib.mu.RLock()
	defer ib.mu.RUnlock()
	env, ok := ib.envelopes[identityID]
	if !ok {
		return nil, false
	}
	if time.Now().UTC().After(env.ExpiresAt) {
		return nil, false
	}
	return env, true
}

func (ib *IdentityBridge) RevokeEnvelope(identityID string) error {
	ib.mu.Lock()
	defer ib.mu.Unlock()
	env, ok := ib.envelopes[identityID]
	if !ok {
		return fmt.Errorf("envelope not found: %s", identityID)
	}
	env.ExpiresAt = time.Now().UTC().Add(-1 * time.Hour)
	return nil
}

func (ib *IdentityBridge) RefreshEnvelope(identityID string) (*TrustEnvelope, error) {
	ib.mu.Lock()
	defer ib.mu.Unlock()
	env, ok := ib.envelopes[identityID]
	if !ok {
		return nil, fmt.Errorf("envelope not found: %s", identityID)
	}
	env.IssuedAt = time.Now().UTC()
	env.ExpiresAt = time.Now().UTC().Add(ib.defaultTTL)
	return env, nil
}

func (ib *IdentityBridge) UpdateTrustScore(identityID string, delta float64) (*TrustEnvelope, error) {
	ib.mu.Lock()
	defer ib.mu.Unlock()
	env, ok := ib.envelopes[identityID]
	if !ok {
		return nil, fmt.Errorf("envelope not found: %s", identityID)
	}
	newScore := env.TrustScore + delta
	if newScore < 0 {
		newScore = 0
	}
	if newScore > 1.0 {
		newScore = 1.0
	}
	env.TrustScore = newScore
	env.TrustLevel = ib.scoreToLevel(newScore)
	env.IssuedAt = time.Now().UTC()
	return env, nil
}

func (ib *IdentityBridge) CreateMapping(internalID, externalID, externalSource, mappingType string, metadata map[string]string) *TrustMapping {
	ib.mu.Lock()
	defer ib.mu.Unlock()

	mapping := &TrustMapping{
		InternalID:      internalID,
		ExternalID:      externalID,
		ExternalSource:  externalSource,
		MappingType:     mappingType,
		MappedAt:        time.Now().UTC(),
		LastVerifiedAt:  time.Now().UTC(),
		MappingMetadata: metadata,
	}

	mappingKey := ib.mappingKey(internalID, externalSource)
	ib.mappings[mappingKey] = mapping
	return mapping
}

func (ib *IdentityBridge) GetMapping(internalID, externalSource string) (*TrustMapping, bool) {
	ib.mu.RLock()
	defer ib.mu.RUnlock()
	mapping, ok := ib.mappings[ib.mappingKey(internalID, externalSource)]
	return mapping, ok
}

func (ib *IdentityBridge) ListMappings(internalID string) []*TrustMapping {
	ib.mu.RLock()
	defer ib.mu.RUnlock()
	var result []*TrustMapping
	for _, m := range ib.mappings {
		if m.InternalID == internalID {
			result = append(result, m)
		}
	}
	return result
}

func (ib *IdentityBridge) ListEnvelopes(nodeID string) []*TrustEnvelope {
	ib.mu.RLock()
	defer ib.mu.RUnlock()
	var result []*TrustEnvelope
	for _, env := range ib.envelopes {
		if nodeID == "" || env.NodeID == nodeID {
			if time.Now().UTC().Before(env.ExpiresAt) {
				result = append(result, env)
			}
		}
	}
	return result
}

func (ib *IdentityBridge) UpdateAttributes(identityID string, attrs *IdentityAttributes) error {
	ib.mu.Lock()
	defer ib.mu.Unlock()
	if _, ok := ib.envelopes[identityID]; !ok {
		return fmt.Errorf("envelope not found: %s", identityID)
	}
	ib.attributes[identityID] = attrs

	env := ib.envelopes[identityID]
	newScore := ib.calculateTrustScore(attrs)
	env.TrustScore = newScore
	env.TrustLevel = ib.scoreToLevel(newScore)
	env.IssuedAt = time.Now().UTC()
	return nil
}

func (ib *IdentityBridge) GetAttributes(identityID string) (*IdentityAttributes, bool) {
	ib.mu.RLock()
	defer ib.mu.RUnlock()
	attrs, ok := ib.attributes[identityID]
	return attrs, ok
}

func (ib *IdentityBridge) calculateTrustScore(attrs *IdentityAttributes) float64 {
	if attrs == nil {
		return 0.0
	}
	score := 0.5

	if attrs.Stake > 0 {
		score += 0.15
		if attrs.Stake > 1000 {
			score += 0.1
		}
	}

	if attrs.Reputation > 0 {
		score += attrs.Reputation * 0.2
	}

	if attrs.TEEType != "" {
		score += 0.1
	}

	if attrs.Environment == "production" {
		score += 0.05
	}

	if len(attrs.Roles) > 0 {
		score += 0.05
	}

	if score > 1.0 {
		score = 1.0
	}
	return score
}

func (ib *IdentityBridge) scoreToLevel(score float64) TrustLevel {
	switch {
	case score >= 0.9:
		return TrustLevelMaximum
	case score >= 0.7:
		return TrustLevelHigh
	case score >= 0.4:
		return TrustLevelMedium
	case score >= 0.1:
		return TrustLevelLow
	default:
		return TrustLevelNone
	}
}

func (ib *IdentityBridge) mappingKey(internalID, externalSource string) string {
	return internalID + ":" + externalSource
}

func (ib *IdentityBridge) FederateIdentity(identityID, federationID string) error {
	ib.mu.Lock()
	defer ib.mu.Unlock()
	env, ok := ib.envelopes[identityID]
	if !ok {
		return fmt.Errorf("envelope not found: %s", identityID)
	}
	env.Federated = true
	env.FederationID = federationID
	return nil
}

func (ib *IdentityBridge) GetStatistics() map[string]interface{} {
	ib.mu.RLock()
	defer ib.mu.RUnlock()
	activeCount := 0
	for _, env := range ib.envelopes {
		if time.Now().UTC().Before(env.ExpiresAt) {
			activeCount++
		}
	}
	return map[string]interface{}{
		"total_envelopes":   len(ib.envelopes),
		"active_envelopes":  activeCount,
		"total_mappings":    len(ib.mappings),
		"trust_distribution": ib.computeTrustDistribution(),
	}
}

func (ib *IdentityBridge) computeTrustDistribution() map[TrustLevel]int {
	dist := map[TrustLevel]int{}
	for _, env := range ib.envelopes {
		if time.Now().UTC().Before(env.ExpiresAt) {
			dist[env.TrustLevel]++
		}
	}
	return dist
}

package policyadapter

import (
	"fmt"
	"sync"
	"time"
)

type PolicySource string

const (
	PolicySourceAGT  PolicySource = "agt"
	PolicySourceOPA  PolicySource = "opa"
	PolicySourceKNIRV PolicySource = "knirv"
)

type NormalizedPolicyInput struct {
	NodeID      string                 `json:"node_id"`
	AgentID     string                 `json:"agent_id,omitempty"`
	Action      string                 `json:"action"`
	ActionType  string                 `json:"action_type"`
	Timestamp   time.Time              `json:"timestamp"`
	Metrics     map[string]float64     `json:"metrics,omitempty"`
	Context     map[string]interface{} `json:"context,omitempty"`
	Labels      map[string]string      `json:"labels,omitempty"`
	Source      PolicySource           `json:"source,omitempty"`
}

type PolicyEvaluation struct {
	PolicyID    string                 `json:"policy_id"`
	PolicyName  string                 `json:"policy_name"`
	Decision    string                 `json:"decision"`
	Reason      string                 `json:"reason,omitempty"`
	Confidence  float64                `json:"confidence"`
	EvaluatedAt time.Time              `json:"evaluated_at"`
	MatchedRules []MatchedRule         `json:"matched_rules,omitempty"`
}

type MatchedRule struct {
	RuleID      string                 `json:"rule_id"`
	RuleName    string                 `json:"rule_name"`
	Decision    string                 `json:"decision"`
	Condition   map[string]interface{} `json:"condition,omitempty"`
	Parameters  map[string]interface{} `json:"parameters,omitempty"`
}

type NormalizedEnforcement struct {
	NodeID         string             `json:"node_id"`
	Action         string             `json:"action"`
	EnforcementID  string             `json:"enforcement_id"`
	Decision       string             `json:"decision"`
	Reason         string             `json:"reason,omitempty"`
	Input          NormalizedPolicyInput `json:"input"`
	Evaluations    []PolicyEvaluation `json:"evaluations,omitempty"`
	EnforcedAt     time.Time          `json:"enforced_at"`
	Source         PolicySource       `json:"source"`
}

type PortabilityContract struct {
	Version        string              `json:"version"`
	Schema         string              `json:"schema"`
	MetricNames    []string            `json:"metric_names"`
	ActionTypes    []string            `json:"action_types"`
	ContextFields  []string            `json:"context_fields"`
	OutputFormat   string              `json:"output_format"`
}

type PolicyAdapter struct {
	mu            sync.RWMutex
	inputs        map[string]*NormalizedPolicyInput
	enforcements  map[string]*NormalizedEnforcement
	contract      PortabilityContract
}

func NewPolicyAdapter() *PolicyAdapter {
	return &PolicyAdapter{
		inputs:       make(map[string]*NormalizedPolicyInput),
		enforcements: make(map[string]*NormalizedEnforcement),
		contract: PortabilityContract{
			Version: "1.0.0",
			Schema:  "https://knirv.network/schemas/policy-input-1.0.json",
			MetricNames: []string{
				"cpu_usage", "memory_usage", "network_bandwidth",
				"execution_time_ms", "token_consumption", "error_rate",
				"latency_p50", "latency_p99", "request_count",
			},
			ActionTypes: []string{
				"execute_tool", "read_file", "write_file",
				"network_request", "spawn_agent", "access_memory",
				"invoke_llm", "deploy_plugin",
			},
			ContextFields: []string{
				"environment", "node_type", "agent_role",
				"session_id", "request_id", "user_id",
			},
			OutputFormat: "application/json",
		},
	}
}

func (pa *PolicyAdapter) GetContract() PortabilityContract {
	pa.mu.RLock()
	defer pa.mu.RUnlock()
	return pa.contract
}

func (pa *PolicyAdapter) NormalizeInput(nodeID, action, actionType string, metrics map[string]float64, context map[string]interface{}) *NormalizedPolicyInput {
	pa.mu.Lock()
	defer pa.mu.Unlock()

	input := &NormalizedPolicyInput{
		NodeID:     nodeID,
		Action:     action,
		ActionType: actionType,
		Timestamp:  time.Now().UTC(),
		Metrics:    metrics,
		Context:    context,
		Labels:     make(map[string]string),
		Source:     PolicySourceKNIRV,
	}

	pa.inputs[pa.inputKey(nodeID, action)] = input
	return input
}

func (pa *PolicyAdapter) RecordEnforcement(input NormalizedPolicyInput, decision, reason string, evaluations []PolicyEvaluation) *NormalizedEnforcement {
	pa.mu.Lock()
	defer pa.mu.Unlock()

	enf := &NormalizedEnforcement{
		NodeID:        input.NodeID,
		Action:        input.Action,
		EnforcementID: fmt.Sprintf("enf-%d", time.Now().UnixNano()),
		Decision:      decision,
		Reason:        reason,
		Input:         input,
		Evaluations:   evaluations,
		EnforcedAt:    time.Now().UTC(),
		Source:        input.Source,
	}

	pa.enforcements[enf.EnforcementID] = enf
	return enf
}

func (pa *PolicyAdapter) GetEnforcement(enfID string) (*NormalizedEnforcement, bool) {
	pa.mu.RLock()
	defer pa.mu.RUnlock()
	enf, ok := pa.enforcements[enfID]
	return enf, ok
}

func (pa *PolicyAdapter) ListEnforcements(nodeID string, limit int) []*NormalizedEnforcement {
	pa.mu.RLock()
	defer pa.mu.RUnlock()

	var result []*NormalizedEnforcement
	for _, enf := range pa.enforcements {
		if nodeID == "" || enf.NodeID == nodeID {
			result = append(result, enf)
		}
	}

	if limit > 0 && len(result) > limit {
		result = result[len(result)-limit:]
	}
	return result
}

func (pa *PolicyAdapter) GetInput(nodeID, action string) (*NormalizedPolicyInput, bool) {
	pa.mu.RLock()
	defer pa.mu.RUnlock()
	input, ok := pa.inputs[pa.inputKey(nodeID, action)]
	return input, ok
}

func (pa *PolicyAdapter) ListInputs(nodeID string, limit int) []*NormalizedPolicyInput {
	pa.mu.RLock()
	defer pa.mu.RUnlock()

	var result []*NormalizedPolicyInput
	for _, inp := range pa.inputs {
		if nodeID == "" || inp.NodeID == nodeID {
			result = append(result, inp)
		}
	}

	if limit > 0 && len(result) > limit {
		result = result[len(result)-limit:]
	}
	return result
}

func (pa *PolicyAdapter) GetStatistics() map[string]interface{} {
	pa.mu.RLock()
	defer pa.mu.RUnlock()

	decisionCounts := map[string]int{}
	for _, enf := range pa.enforcements {
		decisionCounts[enf.Decision]++
	}

	return map[string]interface{}{
		"total_inputs":       len(pa.inputs),
		"total_enforcements": len(pa.enforcements),
		"enforcement_decisions": decisionCounts,
		"contract_version":   pa.contract.Version,
	}
}

func (pa *PolicyAdapter) inputKey(nodeID, action string) string {
	return nodeID + ":" + action
}

package reliability

import (
	"fmt"
	"sync"
	"time"
)

type CircuitState string

const (
	CircuitStateClosed   CircuitState = "closed"
	CircuitStateOpen     CircuitState = "open"
	CircuitStateHalfOpen CircuitState = "half_open"
)

type KillSwitchState string

const (
	KillSwitchStateArmed    KillSwitchState = "armed"
	KillSwitchStateTripped  KillSwitchState = "tripped"
	KillSwitchStateDisarmed KillSwitchState = "disarmed"
)

type EscalationLevel string

const (
	EscalationLevelNone      EscalationLevel = "none"
	EscalationLevelWarning   EscalationLevel = "warning"
	EscalationLevelCritical  EscalationLevel = "critical"
	EscalationLevelShutdown  EscalationLevel = "shutdown"
)

type CircuitBreaker struct {
	State           CircuitState `json:"state"`
	FailureCount    int          `json:"failure_count"`
	SuccessCount    int          `json:"success_count"`
	Threshold       int          `json:"threshold"`
	HalfOpenMax     int          `json:"half_open_max"`
	RecoveryTimeout time.Duration `json:"recovery_timeout"`
	OpenedAt        time.Time    `json:"opened_at,omitempty"`
	LastStateChange time.Time    `json:"last_state_change"`
	mu              sync.RWMutex
}

type ErrorBudget struct {
	TotalBudget    float64       `json:"total_budget"`
	Remaining      float64       `json:"remaining"`
	Consumed       float64       `json:"consumed"`
	Period         time.Duration `json:"period"`
	PeriodStart    time.Time     `json:"period_start"`
	Errors         int           `json:"errors"`
	TotalRequests  int           `json:"total_requests"`
	mu             sync.RWMutex
}

type EscalationPolicy struct {
	WarningThreshold   float64 `json:"warning_threshold"`
	CriticalThreshold  float64 `json:"critical_threshold"`
	ShutdownThreshold  float64 `json:"shutdown_threshold"`
	CooldownPeriod     time.Duration `json:"cooldown_period"`
	AutoReset          bool    `json:"auto_reset"`
}

type KillSwitch struct {
	State          KillSwitchState `json:"state"`
	AgentID        string          `json:"agent_id"`
	NodeID         string          `json:"node_id"`
	Reason         string          `json:"reason,omitempty"`
	TriggeredAt    time.Time       `json:"triggered_at,omitempty"`
	TrippedBy      string          `json:"tripped_by,omitempty"`
	AutoResetAfter time.Duration   `json:"auto_reset_after,omitempty"`
	mu             sync.RWMutex
}

type BreachEvent struct {
	ID          string          `json:"id"`
	AgentID     string          `json:"agent_id"`
	NodeID      string          `json:"node_id"`
	Level       EscalationLevel `json:"level"`
	Reason      string          `json:"reason"`
	MetricName  string          `json:"metric_name,omitempty"`
	MetricValue float64         `json:"metric_value,omitempty"`
	Threshold   float64         `json:"threshold,omitempty"`
	Timestamp   time.Time       `json:"timestamp"`
	Resolved    bool            `json:"resolved"`
	ResolvedAt  *time.Time      `json:"resolved_at,omitempty"`
}

type ReliabilityController struct {
	mu            sync.RWMutex
	breakers      map[string]*CircuitBreaker
	budgets       map[string]*ErrorBudget
	killSwitches  map[string]*KillSwitch
	escalations   map[string]*EscalationPolicy
	breachEvents  []*BreachEvent
	defaultBreakerConfig CircuitBreaker
	defaultBudgetConfig  ErrorBudget
	defaultEscalation    EscalationPolicy
}

func NewReliabilityController() *ReliabilityController {
	return &ReliabilityController{
		breakers:     make(map[string]*CircuitBreaker),
		budgets:      make(map[string]*ErrorBudget),
		killSwitches: make(map[string]*KillSwitch),
		escalations:  make(map[string]*EscalationPolicy),
		breachEvents: make([]*BreachEvent, 0),
		defaultBreakerConfig: CircuitBreaker{
			State:           CircuitStateClosed,
			Threshold:       5,
			HalfOpenMax:     3,
			RecoveryTimeout: 30 * time.Second,
			LastStateChange: time.Now(),
		},
		defaultBudgetConfig: ErrorBudget{
			TotalBudget: 0.1,
			Period:     24 * time.Hour,
			PeriodStart: time.Now(),
		},
		defaultEscalation: EscalationPolicy{
			WarningThreshold:  0.5,
			CriticalThreshold: 0.75,
			ShutdownThreshold: 0.95,
			CooldownPeriod:    5 * time.Minute,
			AutoReset:         true,
		},
	}
}

func (rc *ReliabilityController) GetOrCreateBreaker(breakerID string) *CircuitBreaker {
	rc.mu.Lock()
	defer rc.mu.Unlock()
	cb, ok := rc.breakers[breakerID]
	if !ok {
		cb = &CircuitBreaker{
			State:           CircuitStateClosed,
			Threshold:       rc.defaultBreakerConfig.Threshold,
			HalfOpenMax:     rc.defaultBreakerConfig.HalfOpenMax,
			RecoveryTimeout: rc.defaultBreakerConfig.RecoveryTimeout,
			LastStateChange: time.Now(),
		}
		rc.breakers[breakerID] = cb
	}
	return cb
}

func (rc *ReliabilityController) RecordSuccess(breakerID string) {
	cb := rc.GetOrCreateBreaker(breakerID)
	cb.mu.Lock()
	defer cb.mu.Unlock()

	switch cb.State {
	case CircuitStateClosed:
		cb.SuccessCount++
		cb.FailureCount = 0
	case CircuitStateHalfOpen:
		cb.SuccessCount++
		cb.FailureCount = 0
		if cb.SuccessCount >= cb.HalfOpenMax {
			cb.State = CircuitStateClosed
			cb.LastStateChange = time.Now()
			cb.SuccessCount = 0
		}
	}
}

func (rc *ReliabilityController) RecordFailure(breakerID string) {
	cb := rc.GetOrCreateBreaker(breakerID)
	cb.mu.Lock()
	defer cb.mu.Unlock()

	switch cb.State {
	case CircuitStateClosed:
		cb.FailureCount++
		cb.SuccessCount = 0
		if cb.FailureCount >= cb.Threshold {
			cb.State = CircuitStateOpen
			cb.OpenedAt = time.Now()
			cb.LastStateChange = time.Now()
		}
	case CircuitStateHalfOpen:
		cb.State = CircuitStateOpen
		cb.OpenedAt = time.Now()
		cb.LastStateChange = time.Now()
		cb.FailureCount++
		cb.SuccessCount = 0
	}
}

func (rc *ReliabilityController) IsRequestAllowed(breakerID string) bool {
	cb := rc.GetOrCreateBreaker(breakerID)
	cb.mu.RLock()
	defer cb.mu.RUnlock()

	switch cb.State {
	case CircuitStateClosed:
		return true
	case CircuitStateOpen:
		if time.Since(cb.OpenedAt) >= cb.RecoveryTimeout {
			return true
		}
		return false
	case CircuitStateHalfOpen:
		return cb.SuccessCount < cb.HalfOpenMax
	default:
		return false
	}
}

func (rc *ReliabilityController) GetBreakerState(breakerID string) CircuitState {
	cb := rc.GetOrCreateBreaker(breakerID)
	cb.mu.RLock()
	defer cb.mu.RUnlock()

	if cb.State == CircuitStateOpen && time.Since(cb.OpenedAt) >= cb.RecoveryTimeout {
		return CircuitStateHalfOpen
	}
	return cb.State
}

func (rc *ReliabilityController) ResetBreaker(breakerID string) {
	cb := rc.GetOrCreateBreaker(breakerID)
	cb.mu.Lock()
	defer cb.mu.Unlock()
	cb.State = CircuitStateClosed
	cb.FailureCount = 0
	cb.SuccessCount = 0
	cb.LastStateChange = time.Now()
}

func (rc *ReliabilityController) GetOrCreateBudget(budgetID string) *ErrorBudget {
	rc.mu.Lock()
	defer rc.mu.Unlock()
	b, ok := rc.budgets[budgetID]
	if !ok {
		b = &ErrorBudget{
			TotalBudget: rc.defaultBudgetConfig.TotalBudget,
			Period:      rc.defaultBudgetConfig.Period,
			PeriodStart: time.Now(),
		}
		rc.budgets[budgetID] = b
	}
	return b
}

func (rc *ReliabilityController) ConsumeBudget(budgetID string) (float64, bool) {
	b := rc.GetOrCreateBudget(budgetID)
	b.mu.Lock()
	defer b.mu.Unlock()

	if time.Since(b.PeriodStart) >= b.Period {
		b.Remaining = b.TotalBudget
		b.Consumed = 0
		b.Errors = 0
		b.TotalRequests = 0
		b.PeriodStart = time.Now()
	}

	b.TotalRequests++
	errorRate := float64(b.Errors) / float64(b.TotalRequests)
	if b.TotalRequests == 0 && b.Errors == 0 {
		errorRate = 0
	}

	exhausted := errorRate >= b.Remaining && b.Remaining > 0
	return b.Remaining, !exhausted
}

func (rc *ReliabilityController) RecordBudgetError(budgetID string) {
	b := rc.GetOrCreateBudget(budgetID)
	b.mu.Lock()
	defer b.mu.Unlock()
	b.Errors++
	b.Consumed = float64(b.Errors) / float64(b.TotalRequests)
	if b.TotalRequests == 0 {
		b.TotalRequests = 1
		b.Consumed = 1.0
	}
	b.Remaining = b.TotalBudget - b.Consumed
	if b.Remaining < 0 {
		b.Remaining = 0
	}
}

func (rc *ReliabilityController) GetBudgetStatus(budgetID string) map[string]interface{} {
	b := rc.GetOrCreateBudget(budgetID)
	b.mu.RLock()
	defer b.mu.RUnlock()

	return map[string]interface{}{
		"total_budget":   b.TotalBudget,
		"remaining":      b.Remaining,
		"consumed":       b.Consumed,
		"errors":         b.Errors,
		"total_requests": b.TotalRequests,
		"period_start":   b.PeriodStart,
		"period":         b.Period.String(),
	}
}

func (rc *ReliabilityController) SetupEscalation(nodeID string, policy EscalationPolicy) {
	rc.mu.Lock()
	defer rc.mu.Unlock()
	rc.escalations[nodeID] = &policy
}

func (rc *ReliabilityController) EvaluateEscalation(nodeID string, metricName string, value float64) EscalationLevel {
	rc.mu.RLock()
	policy, ok := rc.escalations[nodeID]
	rc.mu.RUnlock()

	if !ok {
		policy = &rc.defaultEscalation
	}

	switch {
	case value >= policy.ShutdownThreshold:
		return EscalationLevelShutdown
	case value >= policy.CriticalThreshold:
		return EscalationLevelCritical
	case value >= policy.WarningThreshold:
		return EscalationLevelWarning
	default:
		return EscalationLevelNone
	}
}

func (rc *ReliabilityController) ArmKillSwitch(agentID, nodeID string, autoReset time.Duration) *KillSwitch {
	rc.mu.Lock()
	defer rc.mu.Unlock()

	ks := &KillSwitch{
		State:          KillSwitchStateArmed,
		AgentID:        agentID,
		NodeID:         nodeID,
		AutoResetAfter: autoReset,
	}
	rc.killSwitches[rc.killKey(agentID, nodeID)] = ks
	return ks
}

func (rc *ReliabilityController) TripKillSwitch(agentID, nodeID, reason, trippedBy string) (*BreachEvent, error) {
	rc.mu.Lock()
	defer rc.mu.Unlock()

	key := rc.killKey(agentID, nodeID)
	ks, ok := rc.killSwitches[key]
	if !ok {
		return nil, fmt.Errorf("no kill switch found for agent %s on node %s", agentID, nodeID)
	}

	if ks.State == KillSwitchStateTripped {
		return nil, fmt.Errorf("kill switch already tripped for agent %s", agentID)
	}

	ks.State = KillSwitchStateTripped
	ks.Reason = reason
	ks.TrippedBy = trippedBy
	ks.TriggeredAt = time.Now()

	event := &BreachEvent{
		ID:        fmt.Sprintf("breach-%d", time.Now().UnixNano()),
		AgentID:   agentID,
		NodeID:    nodeID,
		Level:     EscalationLevelShutdown,
		Reason:    reason,
		Timestamp: time.Now(),
	}
	rc.breachEvents = append(rc.breachEvents, event)
	return event, nil
}

func (rc *ReliabilityController) DisarmKillSwitch(agentID, nodeID string) error {
	rc.mu.Lock()
	defer rc.mu.Unlock()

	key := rc.killKey(agentID, nodeID)
	ks, ok := rc.killSwitches[key]
	if !ok {
		return fmt.Errorf("no kill switch found for agent %s on node %s", agentID, nodeID)
	}

	ks.State = KillSwitchStateDisarmed
	return nil
}

func (rc *ReliabilityController) GetKillSwitch(agentID, nodeID string) (*KillSwitch, bool) {
	rc.mu.RLock()
	defer rc.mu.RUnlock()
	ks, ok := rc.killSwitches[rc.killKey(agentID, nodeID)]
	return ks, ok
}

func (rc *ReliabilityController) RecordBreachEvent(event *BreachEvent) {
	rc.mu.Lock()
	defer rc.mu.Unlock()
	rc.breachEvents = append(rc.breachEvents, event)
}

func (rc *ReliabilityController) ListBreachEvents(agentID string, limit int) []*BreachEvent {
	rc.mu.RLock()
	defer rc.mu.RUnlock()

	var result []*BreachEvent
	for _, e := range rc.breachEvents {
		if agentID == "" || e.AgentID == agentID {
			result = append(result, e)
		}
	}

	if limit > 0 && len(result) > limit {
		result = result[len(result)-limit:]
	}
	return result
}

func (rc *ReliabilityController) ResolveBreachEvent(eventID string) error {
	rc.mu.Lock()
	defer rc.mu.Unlock()

	for _, e := range rc.breachEvents {
		if e.ID == eventID {
			e.Resolved = true
			now := time.Now()
			e.ResolvedAt = &now
			return nil
		}
	}
	return fmt.Errorf("breach event not found: %s", eventID)
}

func (rc *ReliabilityController) GetStatistics() map[string]interface{} {
	rc.mu.RLock()
	defer rc.mu.RUnlock()

	openBreakers := 0
	totalBreakers := len(rc.breakers)
	for _, cb := range rc.breakers {
		cb.mu.RLock()
		if cb.State == CircuitStateOpen {
			openBreakers++
		}
		cb.mu.RUnlock()
	}

	totalKillSwitches := len(rc.killSwitches)
	tripped := 0
	for _, ks := range rc.killSwitches {
		ks.mu.RLock()
		if ks.State == KillSwitchStateTripped {
			tripped++
		}
		ks.mu.RUnlock()
	}

	unresolvedBreaches := 0
	for _, e := range rc.breachEvents {
		if !e.Resolved {
			unresolvedBreaches++
		}
	}

	return map[string]interface{}{
		"total_circuit_breakers": totalBreakers,
		"open_circuit_breakers":  openBreakers,
		"total_error_budgets":    len(rc.budgets),
		"total_kill_switches":    totalKillSwitches,
		"tripped_kill_switches":  tripped,
		"total_breach_events":    len(rc.breachEvents),
		"unresolved_breaches":    unresolvedBreaches,
	}
}

func (rc *ReliabilityController) killKey(agentID, nodeID string) string {
	return agentID + "@" + nodeID
}

func (rc *ReliabilityController) ListBreakers() map[string]CircuitState {
	rc.mu.RLock()
	defer rc.mu.RUnlock()
	result := make(map[string]CircuitState, len(rc.breakers))
	for id, cb := range rc.breakers {
		cb.mu.RLock()
		state := cb.State
		if state == CircuitStateOpen && time.Since(cb.OpenedAt) >= cb.RecoveryTimeout {
			state = CircuitStateHalfOpen
		}
		result[id] = state
		cb.mu.RUnlock()
	}
	return result
}

func (rc *ReliabilityController) ListKillSwitches() []*KillSwitch {
	rc.mu.RLock()
	defer rc.mu.RUnlock()
	result := make([]*KillSwitch, 0, len(rc.killSwitches))
	for _, ks := range rc.killSwitches {
		result = append(result, ks)
	}
	return result
}

package mcphardening

import (
	"fmt"
	"sync"
	"time"
)

type ToolCallStatus string

const (
	ToolCallStatusAllowed  ToolCallStatus = "allowed"
	ToolCallStatusDenied   ToolCallStatus = "denied"
	ToolCallStatusFlagged  ToolCallStatus = "flagged"
	ToolCallStatusBlocked  ToolCallStatus = "blocked"
)

type PoisoningLevel string

const (
	PoisoningLevelNone      PoisoningLevel = "none"
	PoisoningLevelSuspicious PoisoningLevel = "suspicious"
	PoisoningLevelConfirmed PoisoningLevel = "confirmed"
	PoisoningLevelCritical  PoisoningLevel = "critical"
)

type ToolDefinition struct {
	Name        string   `json:"name"`
	Description string   `json:"description"`
	Parameters  []string `json:"parameters"`
	Required    bool     `json:"required"`
	AllowedIPs  []string `json:"allowed_ips,omitempty"`
	AllowedDomains []string `json:"allowed_domains,omitempty"`
	MaxArgs     int      `json:"max_args,omitempty"`
	Timeout     time.Duration `json:"timeout,omitempty"`
}

type ToolCallRecord struct {
	ID           string            `json:"id"`
	AgentID      string            `json:"agent_id"`
	NodeID       string            `json:"node_id"`
	ToolName     string            `json:"tool_name"`
	Arguments    map[string]interface{} `json:"arguments"`
	Status       ToolCallStatus    `json:"status"`
	Reason       string            `json:"reason,omitempty"`
	Timestamp    time.Time         `json:"timestamp"`
	Duration     time.Duration     `json:"duration,omitempty"`
	TokenCount   int               `json:"token_count,omitempty"`
	PoisoningLevel PoisoningLevel  `json:"poisoning_level,omitempty"`
}

type PoisoningSignature struct {
	Pattern     string            `json:"pattern"`
	Confidence  float64           `json:"confidence"`
	Indicators  []string          `json:"indicators"`
	Severity    PoisoningLevel    `json:"severity"`
}

type MCPEndpoint struct {
	URL          string   `json:"url"`
	AllowedTools []string `json:"allowed_tools"`
	RateLimit    int      `json:"rate_limit"`
	AuthRequired bool     `json:"auth_required"`
}

type ToolCallValidator struct {
	mu           sync.RWMutex
	tools        map[string]*ToolDefinition
	allowedCalls map[string]int
	deniedCalls  map[string]int
	maxCallsPerMin int
}

type PoisoningDetector struct {
	mu           sync.RWMutex
	signatures   []PoisoningSignature
	suspiciousCalls map[string][]string
	threshold    float64
}

type MCPGateway struct {
	mu         sync.RWMutex
	endpoints  map[string]*MCPEndpoint
	auditLog   []*ToolCallRecord
	validator  *ToolCallValidator
	detector   *PoisoningDetector
}

func NewToolCallValidator() *ToolCallValidator {
	return &ToolCallValidator{
		tools:          make(map[string]*ToolDefinition),
		allowedCalls:   make(map[string]int),
		deniedCalls:    make(map[string]int),
		maxCallsPerMin: 100,
	}
}

func (tv *ToolCallValidator) RegisterTool(tool *ToolDefinition) {
	tv.mu.Lock()
	defer tv.mu.Unlock()
	tv.tools[tool.Name] = tool
}

func (tv *ToolCallValidator) GetTool(name string) (*ToolDefinition, bool) {
	tv.mu.RLock()
	defer tv.mu.RUnlock()
	tool, ok := tv.tools[name]
	return tool, ok
}

func (tv *ToolCallValidator) ListTools() []*ToolDefinition {
	tv.mu.RLock()
	defer tv.mu.RUnlock()
	result := make([]*ToolDefinition, 0, len(tv.tools))
	for _, tool := range tv.tools {
		result = append(result, tool)
	}
	return result
}

func (tv *ToolCallValidator) ValidateCall(agentID, toolName string, args map[string]interface{}) (ToolCallStatus, string) {
	tv.mu.Lock()
	defer tv.mu.Unlock()

	tv.allowedCalls[agentID]++

	tool, ok := tv.tools[toolName]
	if !ok {
		return ToolCallStatusFlagged, "unknown tool: " + toolName
	}

	if tool.Required && args == nil {
		return ToolCallStatusDenied, "required tool missing arguments"
	}

	if tool.MaxArgs > 0 && len(args) > tool.MaxArgs {
		return ToolCallStatusDenied, fmt.Sprintf("exceeded max %d arguments", tool.MaxArgs)
	}

	totalAgentCalls := tv.allowedCalls[agentID]
	if totalAgentCalls > tv.maxCallsPerMin {
		return ToolCallStatusBlocked, "rate limit exceeded"
	}

	return ToolCallStatusAllowed, ""
}

func (tv *ToolCallValidator) RecordDeniedCall(agentID string) {
	tv.mu.Lock()
	defer tv.mu.Unlock()
	tv.deniedCalls[agentID]++
}

func (tv *ToolCallValidator) SetMaxCallsPerMin(max int) {
	tv.mu.Lock()
	defer tv.mu.Unlock()
	tv.maxCallsPerMin = max
}

func (tv *ToolCallValidator) GetAgentCallStats(agentID string) map[string]int {
	tv.mu.RLock()
	defer tv.mu.RUnlock()
	return map[string]int{
		"allowed": tv.allowedCalls[agentID],
		"denied":  tv.deniedCalls[agentID],
	}
}

func NewPoisoningDetector() *PoisoningDetector {
	return &PoisoningDetector{
		signatures:      make([]PoisoningSignature, 0),
		suspiciousCalls: make(map[string][]string),
		threshold:       0.7,
	}
}

func (pd *PoisoningDetector) RegisterSignature(sig PoisoningSignature) {
	pd.mu.Lock()
	defer pd.mu.Unlock()
	pd.signatures = append(pd.signatures, sig)
}

func (pd *PoisoningDetector) AnalyzeCall(agentID, toolName string, args map[string]interface{}) (PoisoningLevel, []string) {
	pd.mu.Lock()
	defer pd.mu.Unlock()

	var indicators []string
	maxSeverity := PoisoningLevelNone

	for _, sig := range pd.signatures {
		if sig.Pattern == toolName || pd.matchesToolName(sig.Pattern, toolName) {
			matchConfidence := pd.calculateMatchConfidence(sig, args)
			if matchConfidence >= pd.threshold {
				indicators = append(indicators, sig.Indicators...)
				if pd.severityOrder(sig.Severity) > pd.severityOrder(maxSeverity) {
					maxSeverity = sig.Severity
				}
			}
		}
	}

	if len(indicators) > 0 {
		pd.suspiciousCalls[agentID] = append(pd.suspiciousCalls[agentID], toolName)
		return maxSeverity, indicators
	}

	return PoisoningLevelNone, nil
}

func (pd *PoisoningDetector) GetSuspiciousCallCount(agentID string) int {
	pd.mu.RLock()
	defer pd.mu.RUnlock()
	return len(pd.suspiciousCalls[agentID])
}

func (pd *PoisoningDetector) SetThreshold(t float64) {
	pd.mu.Lock()
	defer pd.mu.Unlock()
	pd.threshold = t
}

func (pd *PoisoningDetector) calculateMatchConfidence(sig PoisoningSignature, args map[string]interface{}) float64 {
	if len(sig.Indicators) == 0 {
		return 0
	}
	return sig.Confidence
}

func (pd *PoisoningDetector) matchesToolName(pattern, toolName string) bool {
	return pattern == toolName
}

func (pd *PoisoningDetector) severityOrder(level PoisoningLevel) int {
	switch level {
	case PoisoningLevelCritical:
		return 4
	case PoisoningLevelConfirmed:
		return 3
	case PoisoningLevelSuspicious:
		return 2
	case PoisoningLevelNone:
		return 1
	default:
		return 0
	}
}

func NewMCPGateway() *MCPGateway {
	return &MCPGateway{
		endpoints: make(map[string]*MCPEndpoint),
		auditLog:  make([]*ToolCallRecord, 0),
		validator: NewToolCallValidator(),
		detector:  NewPoisoningDetector(),
	}
}

func (gw *MCPGateway) Validator() *ToolCallValidator {
	return gw.validator
}

func (gw *MCPGateway) Detector() *PoisoningDetector {
	return gw.detector
}

func (gw *MCPGateway) RegisterEndpoint(name string, ep *MCPEndpoint) {
	gw.mu.Lock()
	defer gw.mu.Unlock()
	gw.endpoints[name] = ep
}

func (gw *MCPGateway) GetEndpoint(name string) (*MCPEndpoint, bool) {
	gw.mu.RLock()
	defer gw.mu.RUnlock()
	ep, ok := gw.endpoints[name]
	return ep, ok
}

func (gw *MCPGateway) ListEndpoints() []*MCPEndpoint {
	gw.mu.RLock()
	defer gw.mu.RUnlock()
	result := make([]*MCPEndpoint, 0, len(gw.endpoints))
	for _, ep := range gw.endpoints {
		result = append(result, ep)
	}
	return result
}

func (gw *MCPGateway) ProcessToolCall(record *ToolCallRecord) ToolCallStatus {
	status, reason := gw.validator.ValidateCall(record.AgentID, record.ToolName, record.Arguments)
	record.Status = status
	record.Reason = reason
	record.Timestamp = time.Now().UTC()

	if status == ToolCallStatusAllowed || status == ToolCallStatusFlagged {
		poisonLevel, indicators := gw.detector.AnalyzeCall(record.AgentID, record.ToolName, record.Arguments)
		record.PoisoningLevel = poisonLevel
		if poisonLevel >= PoisoningLevelConfirmed {
			record.Status = ToolCallStatusBlocked
			record.Reason = fmt.Sprintf("poisoning detected: %v", indicators)
		}
	}

	gw.mu.Lock()
	gw.auditLog = append(gw.auditLog, record)
	gw.mu.Unlock()

	return record.Status
}

func (gw *MCPGateway) GetAuditLog(agentID string, limit int) []*ToolCallRecord {
	gw.mu.RLock()
	defer gw.mu.RUnlock()

	var result []*ToolCallRecord
	for _, rec := range gw.auditLog {
		if agentID == "" || rec.AgentID == agentID {
			result = append(result, rec)
		}
	}

	if limit > 0 && len(result) > limit {
		result = result[len(result)-limit:]
	}
	return result
}

func (gw *MCPGateway) GetStatistics() map[string]interface{} {
	gw.mu.RLock()
	defer gw.mu.RUnlock()

	statusCounts := map[ToolCallStatus]int{}
	poisonCounts := map[PoisoningLevel]int{}
	for _, rec := range gw.auditLog {
		statusCounts[rec.Status]++
		poisonCounts[rec.PoisoningLevel]++
	}

	return map[string]interface{}{
		"total_calls":          len(gw.auditLog),
		"status_distribution":  statusCounts,
		"poisoning_distribution": poisonCounts,
		"registered_tools":     len(gw.validator.tools),
		"registered_endpoints": len(gw.endpoints),
		"registered_signatures": len(gw.detector.signatures),
	}
}

