func (rc *ReliabilityController) ConsumeBudget(budgetID string) (float64, bool) {
	b := rc.GetOrCreateBudget(budgetID)
	b.mu.Lock()
	defer b.mu.Unlock()

	if time.Since(b.PeriodStart) >= b.Period {
		b.Remaining = b.TotalBudget
		b.Consumed = 0
		b.Errors = 0
		b.TotalRequests = 0
		b.PeriodStart = time.Now()
	}

	b.TotalRequests++
	errorRate := float64(b.Errors) / float64(b.TotalRequests)
	if b.TotalRequests == 0 && b.Errors == 0 {
		errorRate = 0
	}

	exhausted := errorRate >= b.Remaining && b.Remaining > 0
	return b.Remaining, !exhausted
}

