 			MaxDiskPerEnv:            cfg.DVEWorkspace.MaxDiskPerEnv,
 			EnableSandboxing:         cfg.DVEWorkspace.EnableSandboxing,
 			EnableNetworkIsolation:   cfg.DVEWorkspace.EnableNetworkIsolation,
